    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id           String    @id @default(cuid())\n  username     String    @unique\n  registration String    @unique\n  passwordHash String\n  role         Role      @default(COMMON)\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n  isActive     Boolean   @default(true)\n  lastLogin    DateTime?\n\n  institutionId String?\n  institution   Institution? @relation(fields: [institutionId], references: [id])\n}\n\nmodel Collect {\n  id            String         @id @default(cuid())\n  collectedAt   DateTime       @default(now())\n  channel       CollectChannel\n  patientHash   String\n  institutionId String?\n  createdAt     DateTime       @default(now())\n  updatedAt     DateTime       @updatedAt\n\n  institution Institution? @relation(fields: [institutionId], references: [id])\n  collectData CollectData?\n\n  @@index([collectedAt])\n  @@index([channel])\n  @@index([patientHash])\n  @@index([institutionId])\n}\n\nmodel Institution {\n  id        String          @id @default(cuid())\n  name      String          @unique\n  type      InstitutionType\n  createdAt DateTime        @default(now())\n  updatedAt DateTime        @updatedAt\n\n  collects Collect[]\n  address  AddressInstitution?\n  users    User[]\n}\n\nmodel AddressInstitution {\n  id           String  @id @default(cuid())\n  street       String\n  number       String\n  complement   String?\n  neighborhood String\n  city         String\n  state        State\n  zipCode      String  @db.VarChar(8) //ex: 53690000\n\n  institutionId String?      @unique\n  institution   Institution? @relation(fields: [institutionId], references: [id])\n}\n\nmodel AddressPatient {\n  id           String  @id @default(cuid())\n  street       String\n  number       String\n  complement   String?\n  neighborhood String\n  city         String\n  state        State\n  zipCode      String  @db.VarChar(8) //ex: 53690000\n\n  patientId String?  @unique\n  patient   Patient? @relation(fields: [patientId], references: [id])\n}\n\nmodel Patient {\n  id               String        @id @default(cuid())\n  name             String\n  cpf              String        @unique @db.VarChar(11)\n  phone            String        @db.VarChar(11)\n  email            String        @unique\n  lastCollectionAt DateTime?\n  patientStatus    PatientStatus @default(ACTIVE)\n  createdAt        DateTime      @default(now())\n  updatedAt        DateTime      @updatedAt\n  birthDate        DateTime\n  sleepQuality     Int\n  isInsomnia       Boolean       @default(false)\n\n  gender    Gender?\n  schooling Schooling?\n\n  address AddressPatient?\n}\n\nmodel CollectData {\n  id        String  @id @default(cuid())\n  collectId String  @unique\n  collect   Collect @relation(fields: [collectId], references: [id])\n\n  // ---------------------------\n  // 1) Perfil do respondente\n  // ---------------------------\n\n  ageRange  AgeRange // opcional: idade exata no momento da coleta\n  gender    Gender? // se quiser coletar\n  schooling Schooling? // escolaridade\n  state     State // redundante mas útil pra analytics direto da coleta\n  city      String\n\n  // ---------------------------\n  // 2) Comportamento digital\n  // ---------------------------\n\n  dailyScreenTimeMin Int // tempo total de tela no dia típico\n  nightUsageMin      Int // uso entre 00h-06h\n  devicesCount       Int // quantos dispositivos usa (cel, pc, tablet)\n\n  // ---------------------------\n  // 3) Questionário / risco\n  // ---------------------------\n\n  dependencyScore      Int // 0-100 padronizado\n  riskLevel            CollectRisk\n  questionnaireVersion String\n\n  // respostas detalhadas (pra recalcular coisas depois, se precisar)\n  rawAnswers Json? // ex: { \"Q1\": 3, \"Q2\": 5, \"Q3\": 1 ... }\n\n  // ---------------------------\n  // 4) Estado emocional / rotina\n  // ---------------------------\n\n  sleepQualityScore       Int // tipo 0–21 ou 0–10 (documenta na app)// sim/não\n  anxietyScore            Int // tipo escala 0–21 ou 0–27\n  depressionScore         Int\n  isolationScore          Int // se sente isolado socialmente\n  physicalActivityPerWeek Int // quantidade de dias/semana com exercício\n\n  // ---------------------------\n  // 5) Metadados de consentimento\n  // ---------------------------\n\n  hasConsent Boolean // aceitou o termo LGPD\n  consentAt  DateTime\n  notes      String? // campo livre curto, se for usar\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([ageRange])\n  @@index([riskLevel])\n  @@index([state])\n  @@index([dependencyScore])\n  @@index([questionnaireVersion])\n}\n\nenum State {\n  AC\n  AL\n  AP\n  AM\n  BA\n  CE\n  DF\n  ES\n  GO\n  MA\n  MT\n  MS\n  MG\n  PA\n  PB\n  PR\n  PE\n  PI\n  RJ\n  RN\n  RS\n  RO\n  RR\n  SC\n  SP\n  SE\n  TO\n}\n\nenum AgeRange {\n  AGE_6a11\n  AGE_12a14\n  AGE_15a17\n  AGE_18a25\n  AGE_26a40\n  AGE_41a59\n  AGE_60a74\n  AGE_75a89\n  AGE_90Plus\n}\n\nenum CollectChannel {\n  PRESENTIAL\n  ONLINE\n}\n\nenum CollectRisk {\n  LOW\n  MEDIUM\n  HIGH\n}\n\nenum Role {\n  ADMIN\n  COMMON\n  PATIENT\n  HEALTH_PROFESSIONAL\n}\n\nenum InstitutionType {\n  HOSPITAL\n  CLINIC\n  SCHOOL\n  COMPANY\n  ONG\n  DEVs\n}\n\nenum PatientStatus {\n  ACTIVE\n  INACTIVE\n  SUSPENDED\n}\n\nenum Gender {\n  MALE\n  FEMALE\n  OTHER\n}\n\nenum Schooling {\n  NO_FORMAL\n  PRE\n  FUNDAMENTAL\n  MEDIUM\n  BACHELOR\n  MASTER\n  DOCTORATE\n}\n",
